const norm = (s: string) => s.toLowerCase().replace(/\s+/g, ' ').trim();
export const LIBRARY = new Map<string, CardInfo>(R.map(([name, t, steps, cues, breathe, easier, harder, preg]) => [norm(name), { t, steps, cues, breathe: breathe || undefined, easier: easier || undefined, harder: harder || undefined, preg }]));

/** The card for an exercise: her own edits, then the library, then a best-guess picture with no text. */
export function cardFor(ex: Exercise): CardInfo & { source: 'custom' | 'library' | 'guess' } {
  const lib = LIBRARY.get(norm(ex.name));
  const base: CardInfo = lib || { t: guessTemplate(ex.name, ex.category), steps: [], cues: [] };
  const own = ex.card;
  if (!own) return { ...base, source: lib ? 'library' : 'guess' };
  return {
    t: own.t || base.t,
    steps: own.steps ?? base.steps,
    cues: own.cues ?? base.cues,
    breathe: own.breathe ?? base.breathe,
    easier: own.easier ?? base.easier,
    harder: own.harder ?? base.harder,
    preg: own.preg ?? base.preg,
    source: 'custom',
  };
}

